import type { PoolOptions } from 'mysql2/promise';

type MySqlExecutorResult = unknown;

export interface MySqlConnectionLike {
  /** Execute prepared SQL/parameters on the explicitly supplied native transport.
   * @param {string} statement - Prepared SQL generated by the shared compiler or fixed transaction controls.
   * @param {unknown[]} params - Separate native parameters; never interpolated into SQL.
   * @returns {Promise<[unknown,unknown]>} Native rows/header plus field metadata.
   */
  execute(statement: string, params?: unknown[]): Promise<[unknown, unknown]>;
  /** Execute fixed transaction-control SQL on the exact acquired lease.
   * @param {string} statement - Prepared SQL generated by the shared compiler or fixed transaction controls.
   * @param {unknown[]} params - Separate native parameters; never interpolated into SQL.
   * @returns {Promise<[unknown,unknown]>} Native control result tuple.
   */
  query(statement: string, params?: unknown[]): Promise<[unknown, unknown]>;
  /** Return a healthy leased connection to its native pool.
   * @returns {void} Host native ownership action; only called once per acquired lease.
   */
  release(): void;
  /** Discard an uncertain or unusable native connection.
   * @returns {void} Does not prove a submitted mutation was rolled back.
   */
  destroy(): void;
}
export type MySqlPoolLike = {
  /** Acquire one native pool lease.
   * @returns {Promise<MySqlConnectionLike>} Lease must expose query/execute/release/destroy.
   */
  getConnection?(): Promise<MySqlConnectionLike>;
  /** Execute prepared SQL/parameters on the explicitly supplied native transport.
   * @param {string} statement - Prepared SQL generated by the shared compiler or fixed transaction controls.
   * @param {unknown[]} params - Separate native parameters; never interpolated into SQL.
   * @returns {Promise<[unknown,unknown]>} Native rows/header plus field metadata.
   */
  execute(
    statement: string,
    params?: unknown[]
  ): Promise<[MySqlExecutorResult, unknown]>;
  /** End a native pool only when its owner requests cleanup.
   * @returns {Promise<void>} Native pool shutdown receipt.
   */
  end?(): Promise<void>;
};

export interface MySqlConnectorOptions extends Record<string, unknown> {
  /** Default 5000ms; integer 1–60000, shortened by caller deadline. */
  acquireTimeoutMs?: number;
  /** Default 32; integer 1–1024 retained through actual acquisition/lease settlement. */
  maxPendingAcquires?: number;
  /** Owned default matched/FOUND_ROWS; injection is only a host handshake assertion. */
  affectedRowsMode?: 'matched' | 'changed';
  /** Only false is supported; multi-statement execution always rejects. */
  multipleStatements?: false;
  /** Optional borrowed query-only transport; pinned transactions remain unsupported. */
  client?: {
    query?: (statement: string, params?: unknown[]) => Promise<unknown>;
    execute?: (statement: string, params?: unknown[]) => Promise<unknown>;
  };
  /** Optional borrowed native pool; getConnection enables the actual pin extension. */
  pool?: MySqlPoolLike;
  /** Trusted native endpoint host. */
  host?: string;
  /** Compatible host alias. */
  hostname?: string;
  /** Compatible native user alias; private host configuration. */
  username?: string;
  /** Private native account name. */
  user?: string;
  /** Private native password; never public config/diagnostics. */
  password?: string;
  /** Explicit trusted database selection. */
  database?: string;
  /** Native TCP port, default 3306, integer 1–65535. */
  port?: number;
  /** Owned pool default 10; integer 1–1024. */
  connectionLimit?: number;
  /** Owned default true with finite queueLimit; wrapper acquisition stays bounded. */
  waitForConnections?: boolean;
  /** Explicit verified certificate/hostname policy; omitted retains local/plain compatibility. */
  ssl?: PoolOptions['ssl'];
  /** Explicit trusted query-only function; no native session is inferred. */
  executor?: (
    statement: string,
    params: unknown[]
  ) => Promise<unknown> | unknown;
}

/** Reject unsafe/mixed transports, unsupported flags and invalid budgets before pool creation.
 * @param {MySqlConnectorOptions} options - Trusted explicit transport/connection policy.
 * @returns {{acquireTimeoutMs:number,maxPendingAcquires:number}} Resolved acquisition/admission limits; injected native policy remains host-owned.
 */
export function validateOptions(options: MySqlConnectorOptions) {
  if (!options || typeof options !== 'object' || Array.isArray(options)) {
    throw new Error('Invalid MySQL options');
  }
  if (
    [options.pool, options.client, options.executor].filter(
      (v) => v !== undefined
    ).length > 1
  ) {
    throw new Error('Ambiguous MySQL transport');
  }
  if (
    options.multipleStatements !== undefined &&
    options.multipleStatements !== false
  ) {
    throw new Error('MySQL multiple statements are disabled');
  }
  if (
    options.affectedRowsMode !== undefined &&
    !['matched', 'changed'].includes(options.affectedRowsMode)
  ) {
    throw new Error('Invalid MySQL affected rows mode');
  }
  // Validate all acquisition/pool/port integer limits before native construction.
  for (const key of [
    'acquireTimeoutMs',
    'maxPendingAcquires',
    'connectionLimit',
    'port',
  ] as const) {
    /** One configured integer validated before creating/acquiring native resources. */
    const value = options[key];
    if (
      value !== undefined &&
      (typeof value !== 'number' ||
        !Number.isSafeInteger(value) ||
        value < 1 ||
        value >
          {
            acquireTimeoutMs: 60000,
            maxPendingAcquires: 1024,
            connectionLimit: 1024,
            port: 65535,
          }[key])
    ) {
      throw new Error('Invalid MySQL limit');
    }
  }
  // Require explicit string-shaped connection fields without logging their values.
  for (const key of [
    'host',
    'hostname',
    'user',
    'username',
    'password',
    'database',
  ] as const) {
    if (options[key] !== undefined && typeof options[key] !== 'string') {
      throw new Error('Invalid MySQL connection option');
    }
  }
  if (
    options.waitForConnections !== undefined &&
    typeof options.waitForConnections !== 'boolean'
  ) {
    throw new Error('Invalid MySQL wait policy');
  }
  // Reject disabling exact BIGINT/DECIMAL string preservation on owned pools.
  for (const [key, expected] of [
    ['supportBigNumbers', true],
    ['bigNumberStrings', true],
    ['decimalNumbers', false],
  ] as const) {
    if (options[key] !== undefined && options[key] !== expected) {
      throw new Error('MySQL precision policy cannot be disabled');
    }
  }
  if (options.ssl !== undefined) {
    if (
      !options.ssl ||
      typeof options.ssl !== 'object' ||
      Array.isArray(options.ssl) ||
      options.ssl.rejectUnauthorized === false ||
      (options.ssl as Record<string, unknown>).verifyIdentity === false
    ) {
      throw new Error('MySQL TLS requires verified certificates');
    }
  }
  if (
    options.pool !== undefined &&
    (!options.pool || typeof options.pool !== 'object')
  ) {
    throw new Error('Invalid MySQL pool');
  }
  if (
    options.client !== undefined &&
    (!options.client || typeof options.client !== 'object')
  ) {
    throw new Error('Invalid MySQL client');
  }
  if (
    (options.pool && typeof options.pool.execute !== 'function') ||
    (options.pool?.getConnection !== undefined &&
      typeof options.pool.getConnection !== 'function')
  ) {
    throw new Error('Invalid MySQL pool');
  }
  if (
    options.executor !== undefined &&
    typeof options.executor !== 'function'
  ) {
    throw new Error('Invalid MySQL executor');
  }
  if (
    options.client &&
    typeof options.client.execute !== 'function' &&
    typeof options.client.query !== 'function'
  ) {
    throw new Error('Invalid MySQL client');
  }
  return {
    acquireTimeoutMs: options.acquireTimeoutMs ?? 5000,
    maxPendingAcquires: options.maxPendingAcquires ?? 32,
  };
}

/** Reuse explicitly injected transports or create one lazy pool with reviewed safety defaults.
 * @param {MySqlConnectorOptions} options - Trusted connection/transport settings; native secrets stay private.
 * @returns {Promise<{pool:MySqlPoolLike,owned:boolean}>} Pool and cleanup ownership; no connection is opened by this helper alone. */
export const createManagedPool = async (
  options: MySqlConnectorOptions
): Promise<{
  /** Optional borrowed native pool; getConnection enables the actual pin extension. */
  pool: MySqlPoolLike;
  owned: boolean;
}> => {
  /** Validated native acquisition timeout and finite queue/admission budget. */
  const limits = validateOptions(options);
  if (options.pool) {
    return { pool: options.pool, owned: false };
  }

  if (options.client || options.executor) {
    return {
      pool: {
        execute: async (statement, params) => {
          if (typeof options.executor === 'function') {
            return [await options.executor(statement, params ?? []), undefined];
          }

          /** Explicit injected execute/query method; invoked with its actual host receiver. */
          const execute = options.client?.execute ?? options.client?.query;
          if (typeof execute !== 'function') {
            throw new Error('MySQL client does not expose execute or query');
          }
          /** Injected native result inspected by the existing tuple compatibility heuristic. */
          const result = await execute.call(options.client, statement, params);
          // mysql2/promise returns [rows, fields], while injected simple clients
          // may return rows directly. Never pass a nested tuple to SQL normalization.
          if (
            Array.isArray(result) &&
            result.length === 2 &&
            (Array.isArray(result[1]) ||
              (result[1] === undefined &&
                result[0] !== null &&
                typeof result[0] === 'object'))
          ) {
            return [result[0], result[1]] as [MySqlExecutorResult, unknown];
          }
          return [result, undefined];
        },
      },
      owned: false,
    };
  }

  /** Fixed lazy mysql2/promise import used only for owned native pools. */
  const mysqlModule = await import('mysql2/promise');
  /** Owned lazy native pool with verified TLS, precision and finite queue policy. */
  const pool = mysqlModule.createPool({
    host: typeof options.host === 'string' ? options.host : options.hostname,
    user: typeof options.user === 'string' ? options.user : options.username,
    password: options.password,
    database:
      typeof options.database === 'string' ? options.database : undefined,
    port: typeof options.port === 'number' ? options.port : 3306,
    connectionLimit:
      typeof options.connectionLimit === 'number'
        ? options.connectionLimit
        : 10,
    waitForConnections:
      typeof options.waitForConnections === 'boolean'
        ? options.waitForConnections
        : true,
    multipleStatements: false,
    supportBigNumbers: true,
    bigNumberStrings: true,
    decimalNumbers: false,
    flags:
      options.affectedRowsMode === 'changed' ? ['-FOUND_ROWS'] : ['FOUND_ROWS'],
    connectTimeout: limits.acquireTimeoutMs,
    queueLimit: limits.maxPendingAcquires,
    ssl: options.ssl
      ? {
          ...(options.ssl as object),
          rejectUnauthorized: true,
          verifyIdentity: true,
        }
      : undefined,
  });

  // The shared SQL executor accepts unknown parameters; mysql2 performs the
  // final runtime validation. Preserve the native pool for getNativeConnection().
  return { pool: pool as unknown as MySqlPoolLike, owned: true };
};
